UPDATE rtc_voice_time 
WHERE participant_sid = #{participantSid} AND room_sid = #{roomSid}
    AND (ended_at IS NULL OR ended_at > #{at})

UPDATE rtc_voice_time SET observing = false
WHERE room_sid = #{roomSid} AND observing AND confirmed_at <= #{at}

    AND participant_sid NOT IN
    #{sid}

UPDATE rtc_voice_time SET observing = false WHERE observing AND confirmed_at <= #{at}

    AND room_sid NOT IN
    #{sid}
